    /// <summary>
    ///  版のずれと機能の印の様子（`ylb_link_report`）。版は `major &lt;&lt; 32 | minor &lt;&lt; 16 | patch`、不明は `u64::MAX`。
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    internal unsafe partial struct YlbLinkReport
    {
        /// <summary>
        ///  相手のアプリの版。
        /// </summary>
